import React, { useState } from 'react';
import PlayerHand from './PlayerHand';
import OtherPlayers from './OtherPlayers';
import DiscardPile from './DiscardPile';

function GameBoard({ gameState, player, onStartGame, onPlayCard, onDrawCard, onLeaveGame }) {
  const [chosenColor, setChosenColor] = useState(null);

  if (!gameState || !player) {
    return <div>Loading...</div>;
  }

  const isCurrentPlayer = gameState.currentPlayer && gameState.currentPlayer._id === player._id;
  const canStartGame = gameState.status === 'waiting' && gameState.players.length >= 2;

  const handlePlayCard = (cardId) => {
    onPlayCard(cardId, chosenColor);
    setChosenColor(null);
  };

  const handleColorChoice = (color) => {
    setChosenColor(color);
  };

  return (
    <div className="game-board">
      <div className="game-header">
        <h2>Game Room: {gameState.roomCode}</h2>
        <div className="game-info">
          <span>Status: {gameState.status}</span>
          <span>Current Color: {gameState.currentColor}</span>
          {gameState.currentPlayer && (
            <span>Current Player: {gameState.currentPlayer.name}</span>
          )}
        </div>
        <button onClick={onLeaveGame} className="leave-button">Leave Game</button>
      </div>

      {gameState.status === 'waiting' && (
        <div className="waiting-room">
          <h3>Waiting for players...</h3>
          <div className="players-list">
            {gameState.players.map((p, index) => (
              <div key={index} className="player-item">
                {p.name} {p._id === player._id && '(You)'}
              </div>
            ))}
          </div>
          {canStartGame && (
            <button onClick={onStartGame} className="start-button">Start Game</button>
          )}
        </div>
      )}

      {gameState.status === 'playing' && (
        <>
          <OtherPlayers gameState={gameState} currentPlayerId={player._id} />
          <DiscardPile discardPile={gameState.discardPile} />
          <div className="game-actions">
            {isCurrentPlayer && (
              <div className="player-actions">
                <button onClick={onDrawCard} className="draw-button">Draw Card</button>
                {chosenColor && (
                  <div className="color-choice">
                    <p>Choose a color:</p>
                    <div className="color-buttons">
                      {['red', 'blue', 'yellow', 'green'].map(color => (
                        <button
                          key={color}
                          className={`color-button ${color}`}
                          onClick={() => handleColorChoice(color)}
                        >
                          {color}
                        </button>
                      ))}
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
          <PlayerHand
            player={player}
            isCurrentPlayer={isCurrentPlayer}
            onPlayCard={handlePlayCard}
          />
        </>
      )}

      {gameState.status === 'finished' && (
        <div className="game-finished">
          <h3>Game Over!</h3>
          {gameState.winner && (
            <p>Winner: {gameState.winner.name}</p>
          )}
        </div>
      )}
    </div>
  );
}

export default GameBoard;
